import{_ as a,o,c as t,ae as d}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"Upgrading","description":"Upgrade Next Laravel from v1.1 to v4. Versions 2 and 3 were never released; the base classes, commands and config keys are unchanged.","frontmatter":{"title":"Upgrading","description":"Upgrade Next Laravel from v1.1 to v4. Versions 2 and 3 were never released; the base classes, commands and config keys are unchanged."},"headers":[],"relativePath":"next-laravel/upgrading.md","filePath":"next-laravel/upgrading.md"}'),s={name:"next-laravel/upgrading.md"};function r(n,e,i,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="upgrading-to-v4" tabindex="-1">Upgrading to v4 <a class="header-anchor" href="#upgrading-to-v4" aria-label="Permalink to &quot;Upgrading to v4&quot;">​</a></h1><p>v4 follows v1.1.0 directly. Versions 2.x and 3.x were never released, so that every Laranex package shares the v4 line. The base classes (<code>Cores\\Controller</code>, <code>Feature</code>, <code>Operation</code>, <code>Job</code>, <code>QueueableJob</code>, <code>Request</code>), the <code>serve()</code>, <code>run()</code> and <code>runInQueue()</code> methods, the command signatures, the config keys and the generated file locations are the same as in v1.1.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>PHP 8.1+ and Laravel 10 to 13 (v1.1 supported Laravel 10 and 11).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/next-laravel:^4.0</span></span></code></pre></div><p>The package no longer depends on <code>spatie/laravel-package-tools</code>; it requires <code>laravel/framework</code> (10 through 13), since it builds on framework-only classes such as <code>FormRequest</code>, <code>DispatchesJobs</code> and <code>ValidatesRequests</code>. If your application relied on the package to pull in <code>spatie/laravel-package-tools</code>, require it yourself.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>The generator commands (<code>next:route</code>, <code>next:controller</code>, <code>next:request</code>, <code>next:feature</code>, <code>next:operation</code>, <code>next:job</code>) now exit with code <code>1</code> when generation fails (for example when the file already exists and <code>--force</code> was not given). In v1.1 they always returned <code>0</code>. Update scripts or CI steps that check the exit code.</p><p>Names containing <code>/</code> or <code>\\</code> (for example <code>next:feature Blog/CreatePost Blog</code>) are now rejected with an error and exit code <code>1</code>; v1.1 wrote a file whose class name contained the slash.</p><p>The second argument of <code>next:operation</code> is now called <code>module</code> instead of <code>domain</code>, matching the other commands. Positional usage (<code>php artisan next:operation SlugifyTitle Blog</code>) is unchanged; only calls that pass the argument by name, such as <code>Artisan::call(&#39;next:operation&#39;, [&#39;operation&#39; =&gt; &#39;SlugifyTitle&#39;, &#39;domain&#39; =&gt; &#39;Blog&#39;])</code>, must use <code>&#39;module&#39;</code> instead.</p><h2 id="config-and-publish-tags" tabindex="-1">Config and publish tags <a class="header-anchor" href="#config-and-publish-tags" aria-label="Permalink to &quot;Config and publish tags&quot;">​</a></h2><p>The config keys <code>enable_routes</code>, <code>web_routes_prefix</code> and <code>api_routes_prefix</code> and their env variables are unchanged, so a published <code>config/next-laravel.php</code> keeps working. The tags <code>next-laravel-config</code>, <code>next-laravel-views</code> and <code>next-laravel-stubs</code> are unchanged, and a new <code>next-laravel</code> tag publishes all three at once.</p><h2 id="stubs" tabindex="-1">Stubs <a class="header-anchor" href="#stubs" aria-label="Permalink to &quot;Stubs&quot;">​</a></h2><p>The queueable job stub declared <code>__construct(): void</code>, which is invalid PHP in every job generated with <code>--queue</code>. If you published the stubs, compare them with the package&#39;s <code>resources/stubs</code> or republish them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;next-laravel-stubs&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>The other stubs keep the same shape: generated route files import the <code>Route</code> facade and use <code>Route::prefix()-&gt;group()</code>, route files use a prefix without a leading slash (<code>Route::prefix(&#39;v1/blogs&#39;)</code>), the feature stub&#39;s <code>handle</code> method declares a <code>mixed</code> return type instead of <code>int</code> and returns <code>null</code> until you fill it in (a feature generated from the old stub threw a <code>TypeError</code> when served unchanged), and unused imports were removed. Fix any job already generated from the old queueable stub by removing <code>: void</code> from its constructor.</p><h2 id="route-registration" tabindex="-1">Route registration <a class="header-anchor" href="#route-registration" aria-label="Permalink to &quot;Route registration&quot;">​</a></h2><p>Route files under <code>routes/web</code> and <code>routes/api</code> are now registered during the service provider&#39;s <code>boot()</code> method instead of <code>register()</code>, so host configuration (including cached config) is honored. Files are loaded in sorted order. Routes are still skipped when the route cache is in use.</p><h2 id="extending-the-package" tabindex="-1">Extending the package <a class="header-anchor" href="#extending-the-package" aria-label="Permalink to &quot;Extending the package&quot;">​</a></h2><ul><li><code>Commands\\BaseCommand</code> is now abstract. Extend it from a concrete command instead of instantiating it.</li><li><code>Laranex\\NextLaravel\\Str</code> no longer overrides <code>studly()</code>; the Laravel method is inherited. If you passed a second argument to <code>Str::studly()</code>, drop it. All other <code>Str</code> helpers take <code>string</code> parameters.</li><li><code>Bus\\Dispatcher::getDispatchableUnit()</code>, <code>serve()</code>, <code>run()</code> and <code>runInQueue()</code> declare native <code>string|object</code> unit and <code>array</code> argument types instead of <code>mixed</code>.</li><li><code>runInQueue()</code> no longer reads <code>composer.json</code> to build the &quot;operation cannot be queued&quot; error, which produced a broken message.</li><li><code>RouteGenerator::getStubContents()</code> is public like the other generators.</li><li><code>NextLaravel::getAllFilesOfADirectory()</code> returns the files sorted.</li><li>Every source file declares <code>strict_types=1</code>.</li></ul>',20)])])}const g=a(s,[["render",r]]);export{p as __pageData,g as default};
